{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '아직 멀었다'는 말이 자동으로 나올 때 뭘 하고 있는 것처럼 느껴지냐고 질문함. 이 핵심신념('내가 하는 일은 무엇이든 결코 충분하지 않다')은 내담자가 언급한 자동적 자기비판 문구의 내용과 직접 일치하며, 성장 배경에서 아버지가 잘한 것은 언급하지 않고 부족한 것만 지적했던 패턴이 이 신념의 기원임."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "'비난을 피하려 매우 높은 내면화된 기준을 충족해야 한다는 강박'은 '아직 멀었다'는 말이 그 순간 수행하는 기능—즉 비난·부족함으로부터 자신을 보호하려는 방어—을 설명하며, 딸이 92점을 가져왔을 때 칭찬 대신 틀린 문제부터 짚은 상황 사례에서 이 강박이 작동하는 방식이 확인됨."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/3"],
      "relevance": "'모든 일을 빈틈없이 해내면 누구도 나를 흠잡지 못하고 내 가치가 유지될 것이다'는 가정이 '아직 멀었다'는 말의 전제 조건에 해당함. 설명회 설문 29장이 긍정적이었는데도 1장의 부정적 의견만 복기한 상황은 이 가정이 작동할 때 어떤 선택이 일어나는지 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": [],
      "relevance": "'기준을 낮추면 결과가 무너지고 사람들이 내가 그 정도밖에 안 되는 사람임을 알게 될 것이다'는 부정적 가정은, '아직 멀었다'는 말이 그 순간 방어하려는 위협의 내용을 설명함—놓으면 무너진다는 공포가 자동 문구를 촉발하는 메커니즘임."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/childhood_data"],
      "relevance": "칭찬을 '아직 멀었다'로 깎아내리는 대처 전략이 내담자가 상담에서 직접 언급한 자동적 문구와 동일하며, 이 전략이 성장 배경에서 반복된 경험(잘한 것은 언급되지 않음)에서 비롯된 것임을 연결함."
    }
  ]
}

